import Foundation

/// Clipboard privacy rules for the whole app. Password managers and other apps mark sensitive
/// or temporary clipboard data with these types (nspasteboard.org conventions). The contents of
/// such items are never read for features — not for history, not for translation.
public enum PasteboardPrivacy {
    public static let concealedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword",
        "de.petermaurer.TransientPasteboardType",
        "com.typeit4me.clipping",
        "Pasteboard generator type",
    ]

    /// Bundle id of the app that wrote the clipboard, which some apps add themselves
    /// (nspasteboard.org). More reliable than the frontmost app at the moment we notice the change.
    public static let sourceType = "org.nspasteboard.source"

    /// Decided from the type list alone, before any data is read.
    public static func isConcealed(_ types: [String]) -> Bool {
        types.contains(where: concealedTypes.contains)
    }
}
